            table.HasCheckConstraint("ck_showcase_moderation_rules_category", "category IN ('Profanity', 'Insult', 'Threat', 'Defamation', 'Racism', 'AdultContent', 'Spam')");
            table.HasCheckConstraint("ck_showcase_moderation_rules_status", "status IN ('Active', 'Inactive')");
        });
        builder.HasKey(x => x.Id);
        builder.Property(x => x.Id).HasColumnName("id");
        builder.Property(x => x.Phrase).HasColumnName("phrase").HasMaxLength(120).IsRequired();
        builder.Property(x => x.Description).HasColumnName("description").HasMaxLength(300).IsRequired();
        builder.Property(x => x.Reason).HasColumnName("reason").HasConversion<string>().HasMaxLength(30);
        // Keep Category explicit: a generated default would omit zero-valued Profanity from seed data.
        builder.Property(x => x.Category).HasColumnName("category").HasConversion<string>().HasMaxLength(32);
        builder.HasOne<ShowcaseViolationCategoryDefinition>().WithMany().HasForeignKey(x => x.Category).OnDelete(DeleteBehavior.Restrict);
        builder.Property(x => x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20).ValueGeneratedNever();
        builder.Property(x => x.CreatedByUserId).HasColumnName("created_by_user_id");
        builder.Property(x => x.CreatedAtUtc).HasColumnName("created_at_utc");
        builder.Property(x => x.UpdatedByUserId).HasColumnName("updated_by_user_id");
        builder.Property(x => x.UpdatedAtUtc).HasColumnName("updated_at_utc");
        builder.HasOne<User>().WithMany().HasForeignKey(x => x.CreatedByUserId).OnDelete(DeleteBehavior.SetNull);
        builder.HasOne<User>().WithMany().HasForeignKey(x => x.UpdatedByUserId).OnDelete(DeleteBehavior.SetNull);
